import"./hoisted.CX6vcqWe.js";document.addEventListener("DOMContentLoaded",()=>{const l=document.querySelectorAll(".filter-btn"),c=document.querySelectorAll(".resource-item");l.forEach(e=>{e.addEventListener("click",()=>{l.forEach(t=>t.classList.remove("active")),e.classList.add("active");const r=e.getAttribute("data-filter");c.forEach(t=>{r==="all"||t.getAttribute("data-category")===r?t.style.display="block":t.style.display="none"})})});const o=document.getElementById("newsletter-form");o&&o.addEventListener("submit",e=>{e.preventDefault();const r=document.getElementById("email").value;document.getElementById("consent").checked,alert(`Thank you for subscribing with ${r}! You'll receive new resources directly to your inbox.`),o.reset()})});
